def transform(grid):
    """Project each colored 1x1 cross center along its row and column.

    The source object is a colored center with four cardinal 3 markers.
    Other 3-marked shapes are not sources. Projection changes background only.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 3):
                continue
            if all(0 <= r + dr < h and 0 <= c + dc < w and
                   grid[r + dr][c + dc] == 3
                   for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                centers.append((r, c, color))
    for r, c, color in centers:
        for j in range(w):
            if grid[r][j] == 0:
                out[r][j] = color
    for r, c, color in centers:
        for i in range(h):
            if grid[i][c] == 0:
                out[i][c] = color
    return out
